type I18nValue = { language: Language; setLanguage: (language: Language) => void; t: (source: string) => string }
const I18nContext = createContext<I18nValue | null>(null)

export function languageFromPath(pathname: string): Language | null {
  const value = pathname.split('/')[1]
  return value === 'en' || value === 'ka' || value === 'ru' ? value : null
}

function preferredLanguage(): Language {
  if (typeof window === 'undefined') return 'en'
  try { const saved = localStorage.getItem('salyior-language'); if (saved === 'en' || saved === 'ka' || saved === 'ru') return saved } catch { /* private mode */ }
  const preferred = navigator.languages?.length ? navigator.languages : [navigator.language]
  if (preferred.some(value => value.toLowerCase().startsWith('ka'))) return 'ka'
  if (preferred.some(value => value.toLowerCase().startsWith('ru'))) return 'ru'
  return 'en'
}

export function localizePath(to: string, language: Language) {
  if (!to.startsWith('/') || to.startsWith('//')) return to
  const match = to.match(/^\/(en|ka|ru)(?=\/|\?|#|$)/)
  return match ? to.replace(/^\/(en|ka|ru)/, `/${language}`) : `/${language}${to === '/' ? '' : to}`
}

export function I18nProvider({ children }: PropsWithChildren) {
  const location = useLocation()
  const navigate = useNavigate()
  const pathLanguage = languageFromPath(location.pathname)
  const [language, setCurrent] = useState<Language>(() => pathLanguage || preferredLanguage())

  useEffect(() => {
    if (pathLanguage) { setCurrent(pathLanguage); document.documentElement.lang = pathLanguage; return }
    document.documentElement.lang = language
    navigate(localizePath(`${location.pathname}${location.search}${location.hash}`, language), { replace: true })
  }, [pathLanguage, language, location.pathname, location.search, location.hash, navigate])

  const setLanguage = useCallback((next: Language) => {
    setCurrent(next)
    try { localStorage.setItem('salyior-language', next) } catch { /* selection still works */ }
    navigate(localizePath(`${location.pathname}${location.search}${location.hash}`, next))
  }, [location.pathname, location.search, location.hash, navigate])

  const t = useCallback((source: string) => copy[source]?.[language] || source, [language])
  const value = useMemo(() => ({ language, setLanguage, t }), [language, setLanguage, t])
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

export function useI18n() {
  const value = useContext(I18nContext)
  if (!value) throw new Error('useI18n must be used inside I18nProvider')
  return value
}
